import { createHash } from "node:crypto";

import type {
  DesignBundle,
  DesignBundleDraft,
  LocalImageRef,
} from "../../../src/design-bundle/schema.ts";

const FIXTURE_ASSET_SHA = "a".repeat(64);
const FIXTURE_ASSET_PATH = `figma/assets/${FIXTURE_ASSET_SHA}.png`;
const FIXTURE_LOGO_SHA = "b".repeat(64);
const FIXTURE_LOGO_PATH = `figma/assets/${FIXTURE_LOGO_SHA}.png`;
const FIXTURE_SCREENSHOT_SHA = "c".repeat(64);
const FIXTURE_SCREENSHOT_PATH = `figma/screenshots/${FIXTURE_SCREENSHOT_SHA}.png`;
const FIXTURE_BLOB_SHA = "d".repeat(64);
const FIXTURE_BLOB_PATH = `figma/screenshots/${FIXTURE_BLOB_SHA}.png`;

export interface M5StaticImageRefs {
  asset: LocalImageRef;
  logo: LocalImageRef;
  screenshot: LocalImageRef;
  blob: LocalImageRef;
}

function sourceHash(sourceId: string): string {
  return createHash("sha256").update(sourceId).digest("hex");
}

function imageRef(
  sha256: string,
  path: string,
  width: number,
  height: number,
): LocalImageRef {
  return {
    path,
    sha256,
    byteCount: 128,
    mimeType: "image/png",
    width,
    height,
  };
}

export function createM5StaticAssetRefs(): LocalImageRef[] {
  const refs = createM5StaticImageRefs();
  return [refs.asset, refs.logo, refs.screenshot, refs.blob];
}

export function createM5StaticImageRefs(): M5StaticImageRefs {
  return {
    asset: imageRef(FIXTURE_ASSET_SHA, FIXTURE_ASSET_PATH, 640, 480),
    logo: imageRef(FIXTURE_LOGO_SHA, FIXTURE_LOGO_PATH, 120, 40),
    screenshot: imageRef(
      FIXTURE_SCREENSHOT_SHA,
      FIXTURE_SCREENSHOT_PATH,
      1440,
      900,
    ),
    blob: imageRef(FIXTURE_BLOB_SHA, FIXTURE_BLOB_PATH, 800, 600),
  };
}

